"""
    Returns a number s for which s^3 ends with the provided suffix.
    :param suffix_bits: the amount of bits in the suffix
    :param suffix: the suffix
    :return: the number s
    """
def attack(suffix_bits: Any, suffix: Any) -> object {
    assert ((suffix % 2) == 1) , "Target suffix must be odd";
    s = 1;
    for i in range(suffix_bits) {
        if ((((s ** 3) >> i) & 1) != ((suffix >> i) & 1)) {
            s |= 1 << i;
        }
    }
    return s;
}

"""Return true if n has two eights in a row.
    >>> double_eights(8)
    False
    >>> double_eights(88)
    True
    >>> double_eights(2882)
    True
    >>> double_eights(880088)
    True
    >>> double_eights(12345)
    False
    >>> double_eights(80808080)
    False
    """
def double_eights(n: Any) -> object {
    temp = 0;
    count = 0;
    while (n > 0) {
        temp = n % 10;
        n //= 10;
        if (temp == 8) {
            count += 1;
        } else {
            count = 0;
        }
        if (count == 2) {
            return True;
        }
    }
    return False;
}

""" Backport of python 3.8's get_origin.  e.g. get_origin(Tuple[str, int]) is Tuple
    :param type_annotation: A type annotation, e.g Tuple[str, int]
    :return: The base type, e.g. Tuple
    """
def get_origin(type_annotation: Any) -> object {
    is_generic_annotation = (
        hasattr(type_annotation, '__origin__')
        and (type_annotation.__origin__ is not None)
    );
    return type_annotation.__origin__ if is_generic_annotation else type_annotation;
}

""" Check that vec1 is less than vec2 elemtwise """
def vec_leq(vec1: Any, vec2: Any) -> object {
    assert isinstance(vec1, `list) , "Only work with lists";
    assert isinstance(vec2, `list) , "Only work with lists";
    assert (len(vec1) == len(vec2)) , "Vector lengths should be the same";
    for (x, y) in zip(vec1, vec2) {
        if (x > y) {
            return False;
        }
    }
    return True;
}

"""Format vertex data.

    :param body: Input body.
    :type body: dict
    :return: Formatted body.
    :rtype: dict
    """
def format_vertex(body: Any) -> object {
    vertex = body['vertex'];
    if ('_oldRev' in vertex) {
        vertex['_old_rev'] = vertex.pop('_oldRev');
    }
    if (('new' in body) or ('old' in body)) {
        result = {'vertex': vertex};
        if ('new' in body) {
            result['new'] = body['new'];
        }
        if ('old' in body) {
            result['old'] = body['old'];
        }
        return result;
    } else {
        return vertex;
    }
}

